define(["jquery"],function($){function isFullscreenActive(){return!!(document.fullscreenElement||document.webkitFullscreenElement||document.mozFullScreenElement||document.msFullscreenElement)}function requestFullscreen(){let element=document.documentElement;let fn=element.requestFullscreen||element.webkitRequestFullscreen||element.mozRequestFullScreen||element.msRequestFullscreen;if(!fn){return false}try{fn.call(element);return true}catch(e){return false}}function showViolationMessage(){let message=$("#proctoringpolicy_fullscreen-message");if(!message.length||!$.trim(message.html())){return}}function hideViolationMessage(){$("#proctoringpolicy_fullscreen-message").hide()}function warnStatus(text){$("#status-danger").show().html(text)}function emitLog(ctx,action,value){$(document).trigger("local_kopere_proctoring:policy_log",[{cmid:ctx.cmid,attemptid:ctx.attemptid,policy:"fullscreen",action:action,value:value||""}])}function bindFullscreenExit(ctx,cfg,state){$(document).on("fullscreenchange webkitfullscreenchange mozfullscreenchange MSFullscreenChange",function(){if(!state.inexam){return}if(!isFullscreenActive()){state.exits=state.exits+1;emitLog(ctx,"fullscreen_exit",String(state.exits));showViolationMessage();if(state.limit>0&&state.exits>state.limit){warnStatus("Fullscreen limit exceeded.");emitLog(ctx,"fullscreen_blocked","limit")}}})}function gateStart(ctx,cfg,state){let startsel="#start-exam,#return-exam-1";$(document).on("click",startsel,function(e){if(isFullscreenActive()){hideViolationMessage();state.inexam=true;return}let ok=requestFullscreen();if(!ok){e.preventDefault();e.stopPropagation();showViolationMessage();warnStatus("Your browser does not support fullscreen.");emitLog(ctx,"fullscreen_not_supported","");return}e.preventDefault();e.stopPropagation();let start=Date.now();let t=setInterval(function(){if(isFullscreenActive()){clearInterval(t);hideViolationMessage();state.inexam=true;emitLog(ctx,"fullscreen_entered","");$(document).trigger("local_kopere_proctoring:fullscreen_ready");return}if(Date.now()-start>3e3){clearInterval(t);showViolationMessage();emitLog(ctx,"fullscreen_failed","")}},100)})}return{init:function(ctx,cfg){let parsedlimit=Number(cfg.limit||0);let state={inexam:false,exits:0,limit:isNaN(parsedlimit)?0:parsedlimit};bindFullscreenExit(ctx,cfg,state);gateStart(ctx,cfg,state);emitLog(ctx,"fullscreen_policy_loaded","")}}});